import{i as e,r as t,s as n,t as r}from"./app-BNhko9A9.js";var i=JSON.parse(`{"path":"/product-bundle/developer-reference.html","title":"Developer Reference","lang":"en-US","frontmatter":{"title":"Developer Reference"},"git":{},"filePathRelative":"product-bundle/developer-reference.md"}`),a={name:`developer-reference.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="developer-reference" tabindex="-1"><a class="header-anchor" href="#developer-reference"><span>Developer Reference</span></a></h1><p>Technical facts for developers integrating with the plugin. Nothing on this page is needed for day-to-day store management.</p><h2 id="product-type" tabindex="-1"><a class="header-anchor" href="#product-type"><span>Product type</span></a></h2><p>The plugin registers the product type slug <code>bundle_product</code>, backed by a <code>WC_Product_Bundle</code> class extending <code>WC_Product</code>. The type appears in the standard <code>product_type_selector</code> and is stored via the normal WooCommerce product-type taxonomy.</p><h2 id="product-meta-keys" tabindex="-1"><a class="header-anchor" href="#product-meta-keys"><span>Product meta keys</span></a></h2><p>Bundle configuration is stored as post meta on the bundle product:</p><table><thead><tr><th>Meta key</th><th>Content</th></tr></thead><tbody><tr><td><code>_bundle_products</code></td><td>Array of items: <code>product_id</code>, <code>quantity</code> (order defines mandatory/optional split)</td></tr><tr><td><code>_bundle_pricing_mode</code></td><td><code>fixed</code> | <code>dynamic</code> (defaults to <code>fixed</code>)</td></tr><tr><td><code>_bundle_fixed_price</code></td><td>Decimal; used in fixed mode; falls back to <code>_regular_price</code> when absent</td></tr><tr><td><code>_bundle_discount_enabled</code></td><td><code>yes</code> | <code>no</code></td></tr><tr><td><code>_bundle_discount_type</code></td><td><code>percent</code> | <code>fixed</code></td></tr><tr><td><code>_bundle_discount_value</code></td><td>Decimal</td></tr><tr><td><code>_bundle_purchase_limit</code></td><td>Positive integer; absent = no limit</td></tr><tr><td><code>_bundle_compulsory_count</code></td><td>Positive integer; absent/0 = all items mandatory</td></tr></tbody></table><p>Order line items receive <code>_bundle_items</code> (the selected contents with quantities and optional flags) plus one visible meta row per included product (&quot;<code>Product x N</code> → <code>Included inside bundle</code>&quot;).</p><h2 id="rest-api" tabindex="-1"><a class="header-anchor" href="#rest-api"><span>REST API</span></a></h2><p>Namespace: <strong><code>product-bundle/v1</code></strong></p><table><thead><tr><th>Route</th><th>Method</th><th>Auth</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/bundle/{id}</code></td><td>GET</td><td>public</td><td>Read a bundle&#39;s pricing mode and items (name, price, quantity, optional flag)</td></tr><tr><td><code>/bundle/get-bundle?id={id}</code></td><td>GET</td><td><code>manage_woocommerce</code> or <code>edit_products</code></td><td>Same payload, admin-oriented</td></tr><tr><td><code>/bundle/get-products?search={term}</code></td><td>GET</td><td><code>manage_woocommerce</code> or <code>edit_products</code></td><td>Product search for admin tooling (20 results)</td></tr><tr><td><code>/bundle/update-bundle</code></td><td>POST/PUT</td><td><code>manage_woocommerce</code> or <code>edit_products</code></td><td>Update <code>pricing_mode</code>, <code>fixed_price</code> and the <code>items</code> array</td></tr></tbody></table><p>Example — read a bundle:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> https://example.com/wp-json/product-bundle/v1/bundle/523</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;pricing_mode&quot;</span><span class="token operator">:</span> <span class="token string">&quot;dynamic&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;items&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span> <span class="token property">&quot;product_id&quot;</span><span class="token operator">:</span> <span class="token number">435</span><span class="token punctuation">,</span> <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Washing Machine&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;price&quot;</span><span class="token operator">:</span> <span class="token string">&quot;1300&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;quantity&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token property">&quot;optional&quot;</span><span class="token operator">:</span> <span class="token boolean">false</span> <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">]</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Example — update a bundle:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST https://example.com/wp-json/product-bundle/v1/bundle/update-bundle <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-u</span> admin:app_password <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;Content-Type: application/json&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-d</span> <span class="token string">&#39;{&quot;id&quot;:523,&quot;pricing_mode&quot;:&quot;dynamic&quot;,&quot;items&quot;:[{&quot;product_id&quot;:435,&quot;quantity&quot;:1}]}&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Invalid bundle IDs return <code>404</code>; an invalid pricing mode returns <code>400</code>.</p><h2 id="hooks" tabindex="-1"><a class="header-anchor" href="#hooks"><span>Hooks</span></a></h2><p>The plugin builds on standard WooCommerce hooks rather than introducing its own filter surface:</p><ul><li>The storefront bundle UI renders on <code>woocommerce_bundle_product_add_to_cart</code> (WooCommerce&#39;s per-type add-to-cart action) and wraps the form with the standard <code>woocommerce_before_add_to_cart_button</code> / <code>woocommerce_after_add_to_cart_button</code> actions.</li><li>Pricing, validation, cart display and order meta use the usual <code>woocommerce_*</code> filters (<code>add_cart_item_data</code>, <code>add_to_cart_validation</code>, <code>before_calculate_totals</code>, <code>get_item_data</code>, <code>checkout_create_order_line_item</code>, <code>is_purchasable</code>, <code>get_price_html</code>, Store API quantity/validation hooks).</li></ul><p>Custom code can therefore interact with bundles through the same WooCommerce hooks it already uses for other product types.</p><h2 id="store-api-blocks" tabindex="-1"><a class="header-anchor" href="#store-api-blocks"><span>Store API / blocks</span></a></h2><p>Purchase-limit enforcement is wired into the WooCommerce Store API (<code>woocommerce_store_api_product_quantity_limit</code> and cart-item validation throwing a <code>409</code> <code>bundle_purchase_limit</code> error), which is what keeps the block cart and checkout consistent with the classic pages.</p><h2 id="templates-and-translations" tabindex="-1"><a class="header-anchor" href="#templates-and-translations"><span>Templates and translations</span></a></h2><ul><li>The admin panel and storefront bundle box are rendered from the plugin&#39;s own <code>templates/</code> directory (they are not theme-overridable template parts in v1.0.0).</li><li>Text domain: <strong><code>product-bundle</code></strong>, Domain Path <code>/languages</code> — all customer-facing strings are translatable with standard tools such as Loco Translate or Poedit.</li></ul>`,25)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};